import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { Chart as ChartJS, ArcElement, Tooltip, Legend, CategoryScale, LinearScale, BarElement } from 'chart.js';
import { Pie, Bar } from 'react-chartjs-2';
import { TrendingUp, Award, Target, CalendarCheck } from 'lucide-react';
import axios from 'axios';

ChartJS.register(ArcElement, Tooltip, Legend, CategoryScale, LinearScale, BarElement);

const ProgressStats = () => {
    const { user, token } = useAuth();
    const [stats, setStats] = useState(null);
    const [tasks, setTasks] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        if (user) {
            fetchData();
        }
    }, [user]);

    const fetchData = async () => {
        try {
            // Fetch tasks
            const tasksRes = await axios.get(
                `http://localhost:8081/api/tasks/user/${user.id}`,
                { headers: { Authorization: `Bearer ${token}` } }
            );
            setTasks(tasksRes.data);

            // Fetch stats
            const statsRes = await axios.get(
                `http://localhost:8081/api/tasks/user/${user.id}/progress`,
                { headers: { Authorization: `Bearer ${token}` } }
            );
            setStats(statsRes.data);
            setLoading(false);
        } catch (error) {
            console.error('Failed to fetch data:', error);
            setLoading(false);
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center h-64">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
            </div>
        );
    }

    // Calculate real stats
    const totalTasks = tasks.length;
    const completedTasks = tasks.filter(t => t.overallCompleted === true).length;
    const completionRate = totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;

    // Task-wise completion
    const javaCompleted = tasks.filter(t => t.javaCompleted === true).length;
    const leetcodeCompleted = tasks.filter(t => t.leetcodeCompleted === true).length;
    const dsaCompleted = tasks.filter(t => t.dsaCompleted === true).length;
    const sqlCompleted = tasks.filter(t => t.sqlCompleted === true).length;
    const projectCompleted = tasks.filter(t => t.projectCompleted === true).length;
    const githubCompleted = tasks.filter(t => t.githubCompleted === true).length;

    const pieData = {
        labels: ['Completed', 'Remaining'],
        datasets: [
            {
                data: [completedTasks, totalTasks - completedTasks],
                backgroundColor: ['#4ade80', '#e5e7eb'],
                borderWidth: 0,
            },
        ],
    };

    const barData = {
        labels: ['Java', 'LeetCode', 'DSA', 'SQL/API', 'Project', 'GitHub'],
        datasets: [
            {
                label: 'Tasks Completed',
                data: [javaCompleted, leetcodeCompleted, dsaCompleted, sqlCompleted, projectCompleted, githubCompleted],
                backgroundColor: [
                    '#3b82f6',
                    '#8b5cf6',
                    '#22c55e',
                    '#f59e0b',
                    '#ef4444',
                    '#06b6d4',
                ],
            },
        ],
    };

    const statsCards = [
        { label: 'Completion Rate', value: `${completionRate}%`, icon: TrendingUp, color: 'text-green-600' },
        { label: 'Days Completed', value: `${completedTasks}/${totalTasks || 30}`, icon: CalendarCheck, color: 'text-blue-600' },
        { label: 'Streak', value: `${stats?.currentStreak || 0} days`, icon: Award, color: 'text-purple-600' },
        { label: 'Target', value: '30 days', icon: Target, color: 'text-orange-600' },
    ];

    return (
        <div className="space-y-6 max-w-7xl mx-auto">
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                {statsCards.map((stat, index) => {
                    const Icon = stat.icon;
                    return (
                        <div key={index} className="bg-white rounded-xl shadow-lg p-6">
                            <div className="flex items-center justify-between">
                                <div>
                                    <p className="text-sm text-gray-600">{stat.label}</p>
                                    <p className="text-2xl font-bold mt-1">{stat.value}</p>
                                </div>
                                <Icon className={`${stat.color} w-8 h-8`} />
                            </div>
                        </div>
                    );
                })}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="bg-white rounded-xl shadow-lg p-6">
                    <h2 className="text-lg font-semibold mb-4">📊 Overall Completion</h2>
                    <div className="max-w-xs mx-auto">
                        <Pie data={pieData} />
                    </div>
                    <div className="text-center mt-4">
                        <p className="text-sm text-gray-500">
                            {completedTasks} of {totalTasks} tasks completed
                        </p>
                    </div>
                </div>

                <div className="bg-white rounded-xl shadow-lg p-6">
                    <h2 className="text-lg font-semibold mb-4">📊 Task-wise Completion</h2>
                    <Bar
                        data={barData}
                        options={{
                            responsive: true,
                            plugins: {
                                legend: {
                                    display: false,
                                },
                            },
                            scales: {
                                y: {
                                    beginAtZero: true,
                                    max: Math.max(10, Math.max(javaCompleted, leetcodeCompleted, dsaCompleted, sqlCompleted, projectCompleted, githubCompleted) + 2),
                                }
                            }
                        }}
                    />
                </div>
            </div>

            <div className="bg-gradient-to-r from-blue-500 to-purple-600 rounded-xl shadow-lg p-8 text-white">
                <h2 className="text-2xl font-bold mb-2">🚀 Keep Going!</h2>
                <p className="opacity-90">
                    You're making great progress! Remember: Consistency is key to mastering development skills.
                </p>
                <div className="mt-4 flex gap-4 flex-wrap">
                    <span className="px-3 py-1 bg-white/20 rounded-full text-sm">#CodeEveryday</span>
                    <span className="px-3 py-1 bg-white/20 rounded-full text-sm">#NeverGiveUp</span>
                    <span className="px-3 py-1 bg-white/20 rounded-full text-sm">#YouCanDoIt</span>
                </div>
            </div>
        </div>
    );
};

export default ProgressStats;
